#include <string>
#include <iostream>

std::string& shorterString(std::string& s1, std::string& s2) {
    // Assume this function returns a non-const reference to the shorter string
    return (s1.size() < s2.size()) ? s1 : s2;
}

std::string& getNonConstVersion(const std::string& constRef) {
    // Hypothetical: We know constRef is actually a reference to a non-const object
    // In practice, add checks before casting
    return const_cast<std::string&>(constRef);  // Removes const for modification
}

int main() {
    std::string str1 = "Hello";
    std::string str2 = "World";
    const std::string& constShorter = shorterString(str1, str2);  // Returns const reference in some contexts
    std::string& modifiableShorter = getNonConstVersion(constShorter);  // Safely cast if str1/str2 are non-const
    modifiableShorter += "!";  // Modify if safe
    std::cout << modifiableShorter << std::endl;  // Output: e.g., "Hello!"
    return 0;
}
